--[[ holon v4 Obfuscator]]
 local function _VM(S,K,Z,C)
    local E=getfenv and getfenv() or _ENV or _G
    local B=bit32 or require("bit")
    local BX=B.bxor or bit.bxor
    -- [Anti-Hook]
    if debug and debug.getinfo then
        local i=debug.getinfo(1,"S")
        if not i or i.what~="Lua" then return end
    end
    -- [Loadstring Hiding]
    local _LS=string.char(108,111,97,100,115,116,114,105,110,103)
    local L=E[_LS] or E["load"]
    if not L then return end
    -- [Decryption]
    local R={}
    for i=1,#S,Z do
        local h,l=0,0
        local hc,lc=string.sub(S,i+Z-2,i+Z-2),string.sub(S,i+Z-1,i+Z-1)
        for j=1,#C do if string.sub(C,j,j)==hc then h=j-1 end if string.sub(C,j,j)==lc then l=j-1 end end
        K=(K*167+13)%65536
        table.insert(R,string.char(BX(h*16+l,K%256)))
    end
    local CD=table.concat(R)
    -- [Anti-Dump] Memory Cleanup
    S=nil;K=nil;Z=nil;C=nil;R=nil
    return L(CD)()
end
